inline uint32_t PredictAction(const float obs[OBS_DIM], float alpha = 0.5f)
{
    float h1[HIDDEN_DIM];
    for (int i = 0; i < HIDDEN_DIM; ++i) {
        float sum = B0[i];
        for (int j = 0; j < OBS_DIM; ++j) {
            sum += W0[i][j] * obs[j];
        }
        h1[i] = std::max(0.0f, sum);
    }

    float h2[HIDDEN_DIM];
    for (int i = 0; i < HIDDEN_DIM; ++i) {
        float sum = B2[i];
        for (int j = 0; j < HIDDEN_DIM; ++j) {
            sum += W2[i][j] * h1[j];
        }
        h2[i] = std::max(0.0f, sum);
    }

    float bestQ = -1e30f;
    uint32_t bestAction = 50;
    const float alphaWeight = 30.0f;
    for (int i = 0; i < ACTION_DIM; ++i) {
        float q = B4[i];
        for (int j = 0; j < HIDDEN_DIM; ++j) {
            q += W4[i][j] * h2[j];
        }
        float delta = static_cast<float>(i - 50);
        q += (alpha - 0.5f) * alphaWeight * delta;
        if (q > bestQ) {
            bestQ = q;
            bestAction = static_cast<uint32_t>(i);
        }
    }
    return bestAction;
}

